// Agrupa por ingeniero×OBRA → un correo por obra (un ingeniero en 2 obras
// recibiría fechas mezcladas bajo un solo nombre de obra si se agrupara solo
// por email).
const porClave = new Map();
for (const item of $input.all()) {
  const r = item.json;
  if (!r.email) continue;
  const k = `${r.email}|${r.nombre_obra || ''}`;
  const e = porClave.get(k) || { email: r.email, nombre: r.nombre || 'Ingeniero', obra: r.nombre_obra || '', dias: new Set() };
  e.dias.add(r.fecha);
  porClave.set(k, e);
}
return [...porClave.values()].map(e => { const dias = [...e.dias].sort(); return { json: {
  email: e.email,
  nombre: e.nombre,
  obra: e.obra,
  n: dias.length,
  lista: dias.map(d => `• ${d}`).join('\n'),
} }; });
